const selfCheckQuestions = [
  'Можешь ли ты своими словами объяснить, как запускается этот язык и какую роль играет пример?',
  'Какие значения и типы используются, и где каждое из них меняется или читается?',
  'Какие условия управляют ходом программы и какие граничные случаи стоит проверить?',
  'Что функция получает, что делает и как её результат используется дальше?',
  'Какие проверки подтвердят, что проект работает правильно и устойчиво?'
];
const STORAGE_KEY = 'code-from-zero-language-progress-v3';
let selectedCourse = courses[0].id;
let activeStep = 0;
let activeTutorial = 0;
let progressByCourse = {};
try {
  const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
  if (saved && typeof saved === 'object' && !Array.isArray(saved)) progressByCourse = saved;
} catch (error) {
  progressByCourse = {};
}

const courseGrid = document.getElementById('courseGrid');
const roadmapList = document.getElementById('roadmapList');
const lessonPanel = document.getElementById('lessonPanel');
const pickerHint = document.querySelector('.picker-hint');
const coursePicker = document.querySelector('.course-picker');
const tutorialScreen = document.getElementById('tutorialScreen');
const tutorialNav = document.getElementById('tutorialNav');
const tutorialLesson = document.getElementById('tutorialLesson');

function getTutorialCompleted(courseId = selectedCourse) {
  const saved = progressByCourse[courseId];
  const total = tutorialUnits.reduce((sum, unit) => sum + unit.lessons.length, 0);
  return new Set(Array.isArray(saved) ? saved.filter(index => Number.isInteger(index) && index >= 0 && index < total) : []);
}

function getCompleted() {
  const saved = progressByCourse[selectedCourse];
  return new Set(Array.isArray(saved) ? saved.filter(index => Number.isInteger(index) && index >= 0 && index < stages.length) : []);
}

function openTutorial(courseId) {
  selectedCourse = courseId;
  activeTutorial = 0;
  activeStep = 0;
  document.body.classList.add('tutorial-open');
  tutorialScreen.hidden = false;
  renderTutorial();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function closeTutorial() {
  document.body.classList.remove('tutorial-open');
  tutorialScreen.hidden = true;
  window.scrollTo({ top: 0, behavior: 'smooth' });
  const firstCourse = courseGrid.querySelector('.course-card');
  if (firstCourse) firstCourse.focus({ preventScroll: true });
}

function renderTutorial() {
  const course = courses.find(item => item.id === selectedCourse);
  const completed = getTutorialCompleted();
  const lessons = tutorialUnits.flatMap((unit, unitIndex) => unit.lessons.map((lesson, lessonIndex) => ({ ...lesson, unitIndex, lessonIndex })));
  const total = lessons.length;
  const progress = Math.round(completed.size / total * 100);
  const lesson = lessons[activeTutorial];
  const step = course.steps[lesson.step];

  document.getElementById('tutorialTitle').textContent = `Изучаем ${course.name} — от нуля до проекта`;
  document.getElementById('tutorialAbout').textContent = `${course.about} В программе ${total} подробных уроков: от устройства языка и базового синтаксиса до отладки и собственного проекта. Проходи их в удобном темпе.`;
  document.getElementById('tutorialProgressText').textContent = `${completed.size} / ${total} уроков · ${progress}%`;
  document.getElementById('tutorialProgressFill').style.width = `${progress}%`;
  document.getElementById('sidebarCount').textContent = `${total} УРОКОВ`;

  tutorialNav.innerHTML = tutorialUnits.map((unit, unitIndex) => {
    const unitLessons = lessons.filter(item => item.unitIndex === unitIndex);
    const unitDone = unitLessons.filter(item => completed.has(lessons.indexOf(item))).length;
    return `<section class="tutorial-unit"><div class="tutorial-unit-heading"><span>${String(unitIndex + 1).padStart(2, '0')} · ${unit.title}</span><small>${unitDone}/${unit.lessons.length}</small></div>${unit.lessons.map((item, lessonIndex) => {
      const index = tutorialUnits.slice(0, unitIndex).reduce((sum, part) => sum + part.lessons.length, 0) + lessonIndex;
      return `<button class="tutorial-nav-item${index === activeTutorial ? ' active' : ''}${completed.has(index) ? ' done' : ''}" type="button" data-lesson="${index}" aria-current="${index === activeTutorial ? 'step' : 'false'}"><span class="tutorial-nav-number">${completed.has(index) ? '✓' : String(lessonIndex + 1).padStart(2, '0')}</span><span>${item.title}</span></button>`;
    }).join('')}</section>`;
  }).join('');

  tutorialNav.querySelectorAll('.tutorial-nav-item').forEach(button => {
    button.addEventListener('click', () => {
      activeTutorial = Number(button.dataset.lesson);
      renderTutorial();
    });
  });

  tutorialLesson.innerHTML = `<div class="tutorial-lesson-content">
    <div class="tutorial-lesson-kicker"><span>ГЛАВА ${String(lesson.unitIndex + 1).padStart(2, '0')} · УРОК ${String(activeTutorial + 1).padStart(2, '0')}</span><span>${lesson.unitIndex === 4 ? 'ПРАКТИКА' : 'ПОШАГОВОЕ ОБУЧЕНИЕ'}</span></div>
    <h2>${lesson.title}</h2>
    <p class="tutorial-lead">${lesson.detail}</p>
    <div class="tutorial-explainer"><span class="tutorial-card-label">КАК ЭТО УСТРОЕНО В ${course.name.toUpperCase()}</span><p>${step[1]}</p><div class="language-note"><strong>Особенность языка</strong><span>${courseNotes[course.id]}</span></div></div>
    <div class="tutorial-code-card"><div class="tutorial-code-heading"><span>РАЗБИРАЕМ ПРИМЕР</span><span>${course.name}</span></div><pre class="example-code"><code>${escapeHtml(step[2])}</code></pre><p>${step[3]}</p></div>
    <div class="tutorial-exercise"><span class="practice-label">ТВОЁ ЗАДАНИЕ</span><p>${lesson.task}</p><div class="tutorial-self-check"><span class="practice-label">ПРОВЕРЬ СЕБЯ</span><p>${lesson.check}</p></div></div>
    <div class="tutorial-controls"><button class="tutorial-prev" type="button" ${activeTutorial === 0 ? 'disabled' : ''}>← Предыдущий урок</button><button class="complete-button${completed.has(activeTutorial) ? ' completed' : ''}" type="button">${completed.has(activeTutorial) ? 'Урок пройден ✓' : 'Отметить урок пройденным'}</button><button class="tutorial-next" type="button" ${activeTutorial === total - 1 ? 'disabled' : ''}>Следующий урок →</button></div>
  </div>`;

  tutorialLesson.querySelector('.tutorial-prev').addEventListener('click', () => {
    if (activeTutorial > 0) { activeTutorial--; renderTutorial(); tutorialLesson.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
  });
  tutorialLesson.querySelector('.tutorial-next').addEventListener('click', () => {
    if (activeTutorial < total - 1) { activeTutorial++; renderTutorial(); tutorialLesson.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
  });
  tutorialLesson.querySelector('.complete-button').addEventListener('click', () => {
    if (completed.has(activeTutorial)) completed.delete(activeTutorial);
    else completed.add(activeTutorial);
    progressByCourse[selectedCourse] = [...completed];
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(progressByCourse)); } catch (error) { /* Progress stays available until the page is closed. */ }
    renderTutorial();
    renderCourses();
  });
}

function renderCourses() {
  const totalLessons = tutorialUnits.reduce((sum, unit) => sum + unit.lessons.length, 0);
  courseGrid.innerHTML = courses.map(course => {
    const done = getTutorialCompleted(course.id).size;
    return `<button class="course-card${course.id === selectedCourse ? ' selected' : ''}" type="button" data-course="${course.id}" aria-pressed="${course.id === selectedCourse}">
      <span class="course-card-top"><span class="course-category">${course.category}</span><span class="course-check">${course.id === selectedCourse ? '✓' : '↗'}</span></span>
      <strong>${course.name}</strong><span class="course-short">${course.short}</span>
      <span class="course-card-bottom"><span>${course.level}</span><span>${done}/${totalLessons}</span></span>
      <span class="course-progress"><span style="width:${Math.round(done / totalLessons * 100)}%"></span></span>
    </button>`;
  }).join('');
  courseGrid.querySelectorAll('.course-card').forEach(button => {
    button.addEventListener('click', () => {
      openTutorial(button.dataset.course);
    });
  });
}

function renderModules() {
  const course = courses.find(item => item.id === selectedCourse);
  const completed = getCompleted();
  pickerHint.textContent = `${course.name} · ${course.about}`;
  coursePicker.setAttribute('aria-label', `Маршрут изучения ${course.name}`);
  roadmapList.innerHTML = stages.map((stage, index) => `
    <button class="module-card${index === activeStep ? ' active' : ''}${completed.has(index) ? ' done' : ''}" type="button" data-index="${index}" aria-pressed="${index === activeStep}">
      <span class="module-index">${completed.has(index) ? '✓' : String(index + 1).padStart(2, '0')}</span>
      <span class="module-info"><strong>${stage.title}</strong><small>${stage.subtitle}</small></span>
      <span class="module-meta">${index === 4 ? 'проект' : `${8 + index * 3} мин`}</span>
    </button>`).join('');
  roadmapList.querySelectorAll('.module-card').forEach(button => {
    button.addEventListener('click', () => {
      activeStep = Number(button.dataset.index);
      renderModules();
      renderLesson();
    });
  });
}

function renderLesson() {
  const course = courses.find(item => item.id === selectedCourse);
  const completed = getCompleted();
  const [title, description, code, tip] = course.steps[activeStep];
  const guide = lessonGuides[activeStep];
  const progress = Math.round(completed.size / stages.length * 100);
  lessonPanel.innerHTML = `
    <div class="lesson-content">
      <div class="lesson-topline"><span>${course.name.toUpperCase()} · ШАГ ${String(activeStep + 1).padStart(2, '0')} / ${String(stages.length).padStart(2, '0')}</span><span class="lesson-badge">${stages[activeStep].label}</span></div>
      <h3>${title}</h3>
      <p class="lesson-description">${description}</p>
      <section class="lesson-deep-dive" aria-label="Подробное объяснение">
        <div class="deep-dive-heading"><span>РАЗБИРАЕМСЯ В ТЕМЕ</span><span>✳</span></div>
        <h4>${guide.heading}</h4>
        <p>${guide.detail}</p>
        <div class="language-note"><strong>Особенность ${course.name}</strong><span>${courseNotes[course.id]}</span></div>
      </section>
      <div class="lesson-example"><div class="example-label">✳ &nbsp;ПРИМЕР КОДА</div><pre class="example-code"><code>${escapeHtml(code)}</code></pre></div>
      <section class="lesson-practice" aria-label="Практика и самопроверка">
        <div class="practice-block"><span class="practice-label">ПОПРОБУЙ САМ</span><p>${guide.practice}</p><p class="practice-extra">${escapeHtml(practiceTasks[activeStep])}</p></div>
        <div class="practice-block self-check"><span class="practice-label">ПРОВЕРЬ СЕБЯ</span><p>${guide.check}</p><p class="practice-extra">${escapeHtml(selfCheckQuestions[activeStep])}</p></div>
      </section>
      <div class="lesson-tip"><span>✦</span><span>${tip}</span></div>
      <div class="lesson-footer"><span class="lesson-time">⌁ &nbsp;${activeStep === 4 ? 'Практика' : `${8 + activeStep * 3} минут`} &nbsp;·&nbsp; в своём темпе</span><button class="complete-button${completed.has(activeStep) ? ' completed' : ''}" type="button">${completed.has(activeStep) ? 'Пройдено ✓' : 'Отметить шаг ✓'}</button></div>
      <div class="progress-line" role="progressbar" aria-label="Прогресс курса ${course.name}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><div class="progress-fill" style="width:${progress}%"></div></div>
      <div class="progress-caption"><span>ПРОГРЕСС · ${course.name.toUpperCase()}</span><span>${completed.size} / ${stages.length} шагов · ${progress}%</span></div>
    </div>`;
  lessonPanel.querySelector('.complete-button').addEventListener('click', () => {
    if (completed.has(activeStep)) completed.delete(activeStep);
    else completed.add(activeStep);
    progressByCourse[selectedCourse] = [...completed];
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(progressByCourse)); } catch (error) { /* Progress remains available until the page is closed. */ }
    renderCourses();
    renderModules();
    renderLesson();
  });
}

function escapeHtml(value) {
  return value.replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
}

document.getElementById('backToHome').addEventListener('click', closeTutorial);
renderCourses();
document.getElementById('year').textContent = new Date().getFullYear();

const revealObserver = new IntersectionObserver(entries => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
      revealObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.15 });
document.querySelectorAll('.reveal').forEach(element => revealObserver.observe(element));
